clean_string() {
  local input="$1"
  echo "$input" | tr '[:upper:]' '[:lower:]' | sed 's/\.[^.]*$//' | sed 's/[^a-z0-9\x80-\xff]//g' | sed 's/ _dup//g'
}

for filepath in *.{mp3,flac,wma,wav,mpc,m4a,mp4,ogg,ape}; do
  [ -f "$filepath" ] || continue
  filename=$(basename "$filepath")
  clean_fn=$(clean_string "$filename")
  matched=0

  echo "🔍 [比对中] 分析文件: \"$filename\" (转换比对键: \"$clean_fn\")"
  # First Pass: Exact or cleaned-key perfect match
  while IFS='|' read -r cat_path artist title clean_db_key; do
    [ -z "$cat_path" ] && continue
    if [ "$clean_fn" = "$clean_db_key" ]; then
      mv "$filepath" "Music/$cat_path/"
      echo "   ↳ ✓【精确匹配成功】已移动: -> Music/$cat_path/"
      MOVED_COUNT=$((MOVED_COUNT+1))
      matched=1
      break
    fi
  done <<< "$database_records"

  # Second Pass: Suffix-tolerant clean-key containment
  if [ $matched -eq 0 ]; then
    while IFS='|' read -r cat_path artist title clean_db_key; do
      [ -z "$cat_path" ] && continue
      [ -z "$clean_db_key" ] && continue
      if [[ "$clean_fn" == *"$clean_db_key"* || "$clean_db_key" == *"$clean_fn"* ]]; then
        mv "$filepath" "Music/$cat_path/"
        echo "   ↳ ~【模糊包含匹配成功】(关键字: $clean_db_key) 已移动: -> Music/$cat_path/"
        MOVED_COUNT=$((MOVED_COUNT+1))
        matched=1
        break
      fi
    done <<< "$database_records"
  fi

  # Third Pass: Artist + Title dual containment checks
  if [ $matched -eq 0 ]; then
    while IFS='|' read -r cat_path artist title clean_db_key; do
      [ -z "$cat_path" ] && continue
      clean_art=$(clean_string "$artist")
      clean_tit=$(clean_string "$title")
      if [ ! -z "$clean_art" ] && [ ! -z "$clean_tit" ]; then
        if [[ "$clean_fn" == *"$clean_art"* && "$clean_fn" == *"$clean_tit"* ]]; then
          mv "$filepath" "Music/$cat_path/"
          echo "   ↳ ⚡【歌手歌名重组匹配成功】($artist - $title) 已移动: -> Music/$cat_path/"
          MOVED_COUNT=$((MOVED_COUNT+1))
          matched=1
          break
        fi
      fi
    done <<< "$database_records"
  fi

  if [ $matched -eq 0 ]; then
    echo "   ↳ ✗ [比对结果落空] 本地音频文件名不属于预设曲库的任何种类，跳过不移动。"
    UNMATCHED_COUNT=$((UNMATCHED_COUNT+1))
  fi
done

